export const getMaterial = id => id === 'custom' ? customMaterial : materials.find(item => item.id === id) || null;

export function customSample(input) {
  if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('请填写自己的练习材料。');
  const text = (key, max, required = false) => {
    const value = input[key] ?? '';
    if (typeof value !== 'string' || value.length > max || required && !value.trim()) throw new Error('材料字段为空或过长，请检查标题、原文和出处。');
    return value;
  };
  const title = text('title', 240, true), original = text('body', 150000, true), note = text('note', 10000);
  const author = text('author', 1000), url = text('url', 2000), locator = text('locator', 2000);
  if (url) {
    let parsed; try { parsed = new URL(url); } catch { throw new Error('出处链接格式无效。'); }
    if (!['http:', 'https:'].includes(parsed.protocol) || parsed.username || parsed.password) throw new Error('出处链接只能使用不含凭据的 HTTP 或 HTTPS 地址。');
  }
  return { title, author, url, locator, platform: '用户自行粘贴的练习材料', body: `${note ? `## 个人心得（用户填写，尚未确认理解）\n\n${note}\n\n` : ''}## 原文（用户粘贴）\n\n${original}\n\n## 用户填写的出处\n\n作者：${author || '未填写'}\n链接：${url || '未填写'}\n位置：${locator || '未填写'}\n\n本材料仅用于独立练习，原文真实性与使用权限由用户核对；没有自动核验或确认理解。` };
}

export function materialSample(id, companion = false) {
  const scene = getMaterial(id);
  if (!scene || id === 'custom') return null;
  const source = companion ? scene.companion : scene.source;
  const excerpt = companion ? source.body : scene.body;
  const attribution = `## 来源与许可\n\n- 原文：${source.title}\n- 作者：${source.author}\n- 链接：${source.url}\n- 位置：${source.locator}\n- 许可：${source.license}（${source.licenseUrl}）\n- 编辑说明：${source.editing || source.locator}\n- 摘录日期：2026-10-03${id === 'tech' ? `\n\n${psfNotice}` : ''}`;
  return { title: `新手练习 · ${source.title}`, body: `${companion ? '' : `## 个人心得（模拟输入，不代表你的理解）\n\n${scene.note}\n\n`}## 原文摘录\n\n${excerpt}\n\n${attribution}`, platform: companion ? '教程伴读原文' : '教程真实原文摘录', author: source.author, url: source.url, locator: source.locator };
}
